g target.","success":"mRNA reached the cytoplasm!","autoPayload":null,"sequenceIndex":null,"codonIndex":null,"uniqueGroup":null,"milestone":null},{"id":"small","kind":"small","group":"Translate","title":"Build the reading station","instruction":"Attach the small ribosome subunit.","payload":"ribosome:small","target":"rna:end5","options":[{"label":"Small subunit","payload":"ribosome:small","detail":"rRNA + proteins","symbol":"capsule.fill","asset":null},{"label":"Large subunit","payload":"ribosome:large","detail":"rRNA + proteins","symbol":"cloud.fill","asset":null}],"learn":["In the eukaryotic workflow shown, the small ribosomal subunit binds the mRNA 5′ cap.","rRNA and proteins form the small and large ribosomal subunits. Ribosomes may be free or attached to rough ER."],"points":20,"hint":"In the eukaryotic workflow shown, the small ribosomal subunit binds the mRNA 5′ cap.","wrong":"Try another tool or the glowing target.","success":"Small subunit attached!","autoPayload":null,"sequenceIndex":null,"codonIndex":null,"uniqueGroup":null,"milestone":null},{"id":"initiator","kind":"initiator","group":"Translate","title":"AUG says start","instruction":"Match a tRNA to AUG.","payload":"trna:UAC","target":"codon:0","options":[{"label":"GCA","payload":"trna:GCA","detail":"3′-GCA-5′ · anticodon choice","symbol":"link","asset":null},{"label":"UAC","payload":"trna:UAC","detail":"3′-UAC-5′ · carries Met","symbol":"link","asset":"CentralTRNACourier"},{"label":"AAA","payload":"trna:AAA","detail":"3′-AAA-5′ · anticodon choice","symbol":"link","asset":null}],"learn":["The initiator tRNA carries methionine (Met). Its 3′-UAC-5′ anticodon pairs with 5′-AUG-3′."],"points":20,"hint":"The initiator tRNA carries methionine (Met). Its 3′-UAC-5′ anticodon pairs with 5′-AUG-3′.","wrong":"Try another tool or the glowing target.","success":"tRNA attached to the start codon!","autoPayload":null,"sequenceIndex":null,"codonIndex":0,"uniqueGroup":null,"milestone":null},{"id":"large","kind":"large"