d":"subunit:2","detail":"Separate polypeptide chain","symbol":"circle.hexagongrid.fill","asset":null},{"label":"Subunit 4","payload":"subunit:3","detail":"Separate polypeptide chain","symbol":"circle.hexagongrid.fill","asset":null}],"learn":["Some proteins assemble from multiple polypeptide chains. Hemoglobin combines four separate subunits.","Each game piece is one separate chain; colors do not name different subunit types."],"points":25,"hint":"Some proteins assemble from multiple polypeptide chains. Hemoglobin combines four separate subunits.","wrong":"Try another tool or the glowing target.","success":"Subunit connected!","autoPayload":null,"sequenceIndex":null,"codonIndex":null,"uniqueGroup":"hemoglobin","milestone":null},{"id":"assemble-3","kind":"assemble","group":"Finish","title":"Hemoglobin example: team up","instruction":"Fit four chains together.","payload":"*","target":"hemoglobin:*","options":[{"label":"Subunit 1","payload":"subunit:0","detail":"Separate polypeptide chain","symbol":"circle.hexagongrid.fill","asset":null},{"label":"Subunit 2","payload":"subunit:1","detail":"Separate polypeptide chain","symbol":"circle.hexagongrid.fill","asset":null},{"label":"Subunit 3","payload":"subunit:2","detail":"Separate polypeptide chain","symbol":"circle.hexagongrid.fill","asset":null},{"label":"Subunit 4","payload":"subunit:3","detail":"Separate polypeptide chain","symbol":"circle.hexagongrid.fill","asset":null}],"learn":["Some proteins assemble from multiple polypeptide chains. Hemoglobin combines four separate subunits.","Each game piece is one separate chain; colors do not name different subunit types."],"points":25,"hint":"Some proteins assemble from multiple polypeptide chains. Hemoglobin combines four separate subunits.","wrong":"Try another tool or the glowing target.","success":"Subunit connected!","autoPayload":null,"sequenceIndex":null,"codonIndex":null,"uniqueGroup":"hemoglobin","milestone":{"title":"Central Dogma champion!","body":"DNA → mRNA → amino acid chain. You did it!","badge":"Gene expression champion"}}]}],"players":[{"id":"dna","title":"Genome, chromosome & gene","caption":"The information library","tint":"blue","scene":"overview","bullets":["**Genome:** all the genetic material within a cell.","**Chromosome:** a discrete package of DNA wrapped around specialized **histone proteins** in the nucleus.","**Gene:** a DNA segment encoding a specific **protein or functional RNA**."]},{"id":"template","title":"The template strand","caption":"The strand that gets copied","tint":"blue","scene":"transcriptionBuild","bullets":["The **template strand** is the DNA strand actually transcribed into RNA.","RNA polymerase reads it **3′ → 5′** and builds RNA **5′ → 3′**, adding to the **3′ end**.","Pairing: DNA **A → RNA U**, **T → A**, **G → C**, **C → G**. **U** means **uracil**."]},{"id":"polymerase","title":"RNA polymerase","caption":"The RNA writer","tint":"blue","asset":"CentralRNAWriter","scene":"transcriptionStart","bullets":["Attaches to DNA at a **promoter**, unzips the double helix, and builds **complementary RNA**.","At termination, it detaches and releases the **RNA transcript**; the DNA rewinds."]},{"id":"signals","title":"Promoter & terminator","caption":"Start here. Finish here.","tint":"sage","scene":"transcriptionEnd","bullets":["**Promoter:** a DNA sequence marking where transcription begins.","**Terminator:** a DNA sequence signaling the end of transcription."]},{"id":"factors","title":"Transcription factors","caption":"Help recruit the writer","tint":"sage","scene":"transcriptionStart","bullets":["In eukaryotes, transcription factors bind **promoters** or distant **enhancers**, attracting **RNA polymerase**.","**TATA-binding protein** is one example of a transcription factor."]},{"id":"mrna","title":"mRNA & codons","caption":"A recipe read three bases at a time","tint":"butter","scene":"translationStart","bullets":["**Messenger RNA (mRNA)** carries the genetic recipe from the **nucleus** to the **cytoplasm**.","A **codon** is three consecutive mRNA bases specifying **one amino acid or a stop signal**.","The **genetic code** matches **64 triplet codons** to **20 amino acids or stop signals**."]},{"id":"trna","title":"tRNA & anticodon","caption":"Match the message. Deliver the amino acid.","tint":"sage","asset":"CentralTRNACourier","scene":"translationBuild","bullets":["**Transfer RNA (tRNA)** carries a specific **amino acid** at one end and a three-base **anticodon** loop at the other.","The anticodon binds its complementary **mRNA codon**. At initiation, **5′-AUG-3′** pairs with **3′-UAC-5′**.","The initiator tRNA carries **methionine (Met)**. Empty tRNA leaves to pick up another amino acid in the **cytosol**."]},{"id":"ribosome","title":"rRNA & ribosome","caption":"The protein-building station","tint":"lavender","asset":"CentralRibosome","scene":"translationStart","bullets":["**Ribosomal RNA (rRNA)** and proteins form the ribosome’s **small and large subunits**.","Ribosomes are the site of **translation**, free in the cytoplasm or attached to the **rough endoplasmic reticulum**.","The small subunit binds first; the large subunit joins after the initiator tRNA matches **AUG**."]},{"id":"processing","title":"The mRNA editing crew","caption":"Cap. Tail. Splice.","tint":"peach","scene":"processing","bullets":["The **5′ cap** is a modified nucleotide: protection from degradation and help with ribosome binding.","The **3′ poly A tail** adds **100–200 adenines** for stability and translation efficiency.","Small catalytic **RNAs and proteins** remove non-coding **introns** and join retained **exons**. Mature mRNA then leaves the nucleus."]},{"id":"elongation","title":"Peptide bonds & elongation factors","caption":"Keep the chain growing","tint":"peach","scene":"translationBuild","bullets":["The ribosome makes covalent **peptide bonds** between amino acids.","**Elongation factors** help tRNAs deliver amino acids as the ribosome advances **5′ → 3′**, one codon at a time.","The growing amino acid chain is a **polypeptide**."]},{"id":"release","title":"Stop codons & release factors","caption":"The finish signal is not an amino acid","tint":"lavender","scene":"translationEnd","bullets":["The three stop codons are **UGA, UAA, and UAG**.","Stop codons have **no matching tRNA**. **Release factor proteins** bind instead.","Release factors trigger polypeptide release and separation of **ribosomal subunits, tRNA, and mRNA**."]},{"id":"chaperones","title":"Chaperone proteins","caption":"Help the chain find its shape","tint":"sage","scene":"folding","bullets":["A polypeptide folds into its functional **3D protein shape**.","**Chaperone proteins** aid and stabilize folding."]},{"id":"finishing","title":"Cleavage & assembly","caption":"The finishing crew","tint":"peach","scene":"finishing","bullets":["**Cleavage enzymes** cut some proteins into functional pieces: **proinsulin → 51-amino-acid insulin**.","**Assembly** brings separate polypeptide chains together: **hemoglobin has four subunits**."]}]}
